diff --git a/OfficeIMO.Excel/Read/ExcelSheetReader.XmlAttributes.cs b/OfficeIMO.Excel/Read/ExcelSheetReader.XmlAttributes.cs
index 5ed2e8e8f058d6dd46ada8a6da10779e6823ca1a..128ccedf998492616342014823e9efa190f82e2d 100644
--- a/OfficeIMO.Excel/Read/ExcelSheetReader.XmlAttributes.cs
+++ b/OfficeIMO.Excel/Read/ExcelSheetReader.XmlAttributes.cs
@@ -74,6 +74,9 @@ namespace OfficeIMO.Excel {
                 const int chunkLength = 32;
                 char[] buffer = _xmlAttributeTextBuffer ??= new char[chunkLength * 2];
                 int length = reader.ReadValueChunk(buffer, 0, chunkLength);
+                // The framework reader fills attribute chunks unless the value ends
+                // or a surrogate pair crosses the last slot. Probe that boundary.
+                if (length < chunkLength - 1) return buffer.AsSpan(0, length);
                 int following = reader.ReadValueChunk(buffer, chunkLength, chunkLength);
                 if (following == 0) return buffer.AsSpan(0, length);
                 var builder = new StringBuilder(length + following);
diff --git a/OfficeIMO.Excel/Read/ExcelSheetReader.XmlCoordinates.cs b/OfficeIMO.Excel/Read/ExcelSheetReader.XmlCoordinates.cs
index d996f66793c254f222005845c8982ab8b8ee9a73..99c1184dc92d3a46649003d843ddf019de4536b8 100644
--- a/OfficeIMO.Excel/Read/ExcelSheetReader.XmlCoordinates.cs
+++ b/OfficeIMO.Excel/Read/ExcelSheetReader.XmlCoordinates.cs
@@ -39,6 +39,9 @@ namespace OfficeIMO.Excel {
                 const int chunkLength = 32;
                 char[] buffer = _xmlCoordinateTextBuffer ??= new char[chunkLength * 2];
                 int length = reader.ReadValueChunk(buffer, 0, chunkLength);
+                // Framework attribute chunks can be one character short when a
+                // surrogate pair crosses the boundary; shorter values are complete.
+                if (length < chunkLength - 1) return new XmlCoordinateReference(buffer.AsSpan(0, length));
                 // A short chunk can end before a surrogate pair, rather than at EOF.
                 // Keep the first chunk intact while checking for additional content.
                 int followingLength = reader.ReadValueChunk(buffer, chunkLength, chunkLength);

QualificationScript:
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
Set-Location $repo
$record = Get-Content (Join-Path $PSScriptRoot 'chunk-provenance.json') -Raw | ConvertFrom-Json
function Assert-Frozen {
    git diff --no-ext-diff --no-textconv --no-color --full-index --binary --output=Ignore/Benchmarks/excel-xml-buffer/chunk-running.patch -- OfficeIMO.Excel
    if ($LASTEXITCODE -or (Get-FileHash (Join-Path $PSScriptRoot 'chunk-running.patch')).Hash -ne $record.PatchHash) { throw 'Source changed during qualification' }
    $manifest=Get-Content (Join-Path $PSScriptRoot 'chunk-final-binary-manifest.json') -Raw | ConvertFrom-Json
    foreach($item in $manifest) {
        foreach($side in 'baseline','candidate') {
            if((Get-FileHash (Join-Path $PSScriptRoot "$side-excel/$($item.File)")).Hash -ne $item.$side) { throw "Binary changed: $side/$($item.File)" }
        }
    }
}
Assert-Frozen
$env:OFFICEIMO_PERFORMANCE_SNAPSHOTS = $PSScriptRoot
$env:OFFICEIMO_BENCHMARK_DATA = Join-Path (Split-Path $PSScriptRoot -Parent) 'excel-csv-attributes/fixtures'
$env:OFFICEIMO_BENCHMARK_OUTPUT = Join-Path $PSScriptRoot 'files'
$env:OFFICEIMO_COMPARISON_MASK = '65535'
$env:OFFICEIMO_BENCHMARK_PROCESS_PRIORITY = 'Normal'
$env:OFFICEIMO_COMPARISON_CASES = Join-Path $PSScriptRoot 'chunk-final-small-cases.json'
$runner = Join-Path (Split-Path $PSScriptRoot -Parent) 'excel-csv-broad/compare/bin/Release/net10.0/Compare.dll'
dotnet $runner --validate *> (Join-Path $PSScriptRoot 'chunk-final-validation.log')
if ($LASTEXITCODE) { throw 'Output validation failed' }
Write-Output 'Validated all 38 small qualification workloads.'
Push-Location (Resolve-Path (Join-Path (Split-Path $runner) '../../..'))
try {
    foreach ($group in 'large','small') {
        $file = if ($group -eq 'large') { 'large-cases.json' } else { 'chunk-final-small-cases.json' }
        $env:OFFICEIMO_COMPARISON_CASES = Join-Path $PSScriptRoot $file
        $output = Join-Path $PSScriptRoot "chunk-final-$group-native"
        if (Test-Path $output) { throw 'Qualification output exists' }
        $warmup = if ($group -eq 'large') { 5 } else { 24 }
        $iterations = if ($group -eq 'large') { 5 } else { 12 }
        $operations = if ($group -eq 'large') { 1 } else { 4 }
        $count = if ($group -eq 'large') { 8 } else { 76 }
        dotnet $runner --filter '*SnapshotComparison*' --warmupCount $warmup --iterationCount $iterations --invocationCount $operations --unrollFactor 1 --outliers DontRemove --artifacts $output *> "$output.log"
        if ($LASTEXITCODE) { throw "$group qualification failed" }
        $report = Get-Content (Join-Path $output 'results/SnapshotComparison-report-full.json') -Raw | ConvertFrom-Json
        if ($report.Benchmarks.Count -ne $count -or @($report.Benchmarks | Where-Object { $_.Statistics.N -ne $iterations }).Count) { throw "Incomplete $group qualification" }
        Write-Output "Completed $count $group native cases."
    }
} finally { Pop-Location }
Assert-Frozen
foreach ($mask in 65535L,4294901760L) {
    pwsh -NoProfile -File (Join-Path $PSScriptRoot 'rotated.ps1') -Mask $mask -Iterations 12 -Warmup 3 -Operations 1 -Cases large-cases.json -Label chunk-final-large-rotated *> (Join-Path $PSScriptRoot "chunk-final-large-rotated-$mask.log")
    if ($LASTEXITCODE) { throw "Large rotation failed: $mask" }
    Write-Output "Completed large rotation: $mask"
    pwsh -NoProfile -File (Join-Path $PSScriptRoot 'rotated.ps1') -Mask $mask -Cases chunk-final-small-cases.json -Label chunk-final-small-rotated *> (Join-Path $PSScriptRoot "chunk-final-small-rotated-$mask.log")
    if ($LASTEXITCODE) { throw "Small rotation failed: $mask" }
    Assert-Frozen
    Write-Output "Completed small rotation: $mask"
}

RotatedScript:
param([long] $Mask = 65535, [int] $Iterations = 24, [int] $Warmup = 12, [int] $Operations = 4,
    [string] $Cases = 'rotated-cases.json', [string] $Label = 'rotated', [switch] $IdenticalBaseline)
$ErrorActionPreference = 'Stop'
Import-Module PSPublishModule
$env:OFFICEIMO_PERFORMANCE_SNAPSHOTS = $PSScriptRoot
$env:OFFICEIMO_COMPARISON_CASES = Join-Path $PSScriptRoot $Cases
$env:OFFICEIMO_PERFORMANCE_AA = if ($IdenticalBaseline) { '1' } else { '0' }
$env:OFFICEIMO_BENCHMARK_DATA = Join-Path (Split-Path $PSScriptRoot -Parent) 'excel-csv-attributes/fixtures'
$env:OFFICEIMO_BENCHMARK_OUTPUT = Join-Path $PSScriptRoot 'files'
[Diagnostics.Process]::GetCurrentProcess().ProcessorAffinity = [IntPtr]::new($Mask)
[Diagnostics.Process]::GetCurrentProcess().PriorityClass = 'Normal'
[Reflection.Assembly]::LoadFrom((Join-Path (Split-Path $PSScriptRoot -Parent) 'excel-csv-broad/compare/bin/Release/net10.0/Compare.dll')) | Out-Null
$global:BroadProbes = @{}
$global:BroadExpected = @{}
$global:BroadOperations = $Operations
foreach ($key in [SnapshotProbe]::Keys()) {
    $before = [SnapshotProbe]::Load($key, 'baseline')
    $after = [SnapshotProbe]::Load($key, 'candidate')
    $expected = $before.RunSynchronously().ToString()
    if ($after.RunSynchronously().ToString() -ne $expected) { throw "Validation failed: $key" }
    $global:BroadProbes[$key] = @{ Before = $before; After = $after }
    $global:BroadExpected[$key] = $expected
}
try {
    $result = Invoke-BenchmarkSuite -OutputRoot (Join-Path $PSScriptRoot "$Label-$Mask") -WarmupCount $Warmup -IterationCount $Iterations -RunOrder Rotated -OutlierMode None -Settings {
        New-BenchmarkSuite 'Excel CSV broad qualification' {
            Add-BenchmarkMetadata AffinityMask $Mask
            Add-BenchmarkMetadata OperationsPerSample $Operations
            Add-BenchmarkMetadata IdenticalBaseline ([string]$IdenticalBaseline)
            Add-BenchmarkMetadata Priority ([Diagnostics.Process]::GetCurrentProcess().PriorityClass.ToString())
            Add-BenchmarkCaseSource @($global:BroadProbes.Keys | Sort-Object | ForEach-Object { [pscustomobject]@{Name=$_} })
            Set-BenchmarkSetup {
                param($case, $run)
                $run.Probe = $global:BroadProbes[$case.Scenario][$case.Engine]
                $run.Expected = $global:BroadExpected[$case.Scenario]
            }
            foreach ($engine in 'Before','After') {
                Add-BenchmarkEngine $engine {
                    Add-BenchmarkOperation ReadBatch {
                        param($case, $run)
                        for ($i=0; $i -lt $global:BroadOperations; $i++) { $run.Result = $run.Probe.RunSynchronously() }
                    }
                }
            }
            Add-BenchmarkValidation {
                param($case, $run)
                if ($run.Result.ToString() -ne $run.Expected) { throw 'Output differs from validated setup.' }
            }
            Add-BenchmarkComparison -Baseline Before -Metric MeanMs,MedianMs -TieTolerance 0.05
        }
    }
    if (@($result.Samples | Where-Object Status -ne 'Succeeded').Count -gt 0) {
        throw 'Comparison contains failed samples; inspect the retained artifacts.'
    }
    $result
} finally {
    foreach ($pair in $global:BroadProbes.Values) { $pair.Before.Dispose(); $pair.After.Dispose() }
}

