    if ($LASTEXITCODE -or (Get-FileHash (Join-Path $PSScriptRoot 'chunk-regression.patch')).Hash -ne 'D864DB07E281CFC825FB6DDAA42A4B0F4EC430239B1DC5A198171D5B991FF2C3') { throw 'XML source changed.' }
